// p2sdk T-02 fake LLM provider, loaded inside the dsh runtime through the
// P2SDK_PATCH overlay generated by tests/support/fake/harness.ts.
//
// Scripted-response adapter logic 来源 (copied minimal, MIT):
//   https://github.com/deepseek-ai/deepseek-harness@ce7073d51254c26cd63b22a60835b8f948deb447
//   packages/core/agent-loop/tests/mock-adapter.ts   — scripted stream() + abort/hang pattern
//   packages/llm/llm/src/index.ts LlmAdapter         — default member bodies (see FakeAdapter)
// dsh-llm-replay only offers paceMs pacing — no cross-process barrier
// (work/p2-sdk/reuse/dsh-as-dependency.md:74) — so the gate-file wait after
// the first chunk is ours. Scripts, gates, and the request log live under
// $P2SDK_HOME/fake (contract with harness.ts).
//
// The adapter is duck-typed instead of `extends LlmAdapter`: the dsh plugin
// loader relocates bare-specifier resolution into its own scope, so
// '@deepseek-ai/dsh-llm' cannot be imported from this file; registerAdapter
// only requires the member surface below (verified against llm/src/index.ts
// prepareRoutes/resolveModelInfoFor/prepareCall at ce7073d).
import { appendFileSync, existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

export const name = 'p2sdk-fake-llm'
export const inject = ['llm']

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

function fakeHome() {
  // T-12 (REVIEW R1): P2SDK_HOME no longer enters the dsh env; DSH_HOME is the
  // canonical home and the upstream scrubber keeps it out of model-driven
  // tool processes, so scripts/gates stay operator-side only.
  const home = process.env.DSH_HOME
  if (!home) throw new Error('p2sdk-fake-llm: $DSH_HOME is not set')
  return home
}

/** Wait until the T-01⑧ gate file appears; abort rejects (MockAdapter hang pattern). */
async function waitForGate(path, signal) {
  if (existsSync(path)) return
  if (signal?.aborted) throw new Error(`p2sdk-fake-llm: aborted at gate ${path}`)
  await new Promise((resolve, reject) => {
    const stop = () => {
      clearInterval(poll)
      reject(new Error(`p2sdk-fake-llm: aborted at gate ${path}`))
    }
    const poll = setInterval(() => {
      if (existsSync(path)) {
        clearInterval(poll)
        signal?.removeEventListener('abort', stop)
        resolve()
      }
    }, 25)
    signal?.addEventListener('abort', stop, { once: true })
  })
}

class FakeAdapter {
  constructor(providers) {
    this.providers = providers
    this.cursors = new Map()
  }

  // --- LlmAdapter default member bodies (copied from packages/llm/llm/src/index.ts) ---

  providerInfo(provider) {
    return { id: provider, name: provider }
  }

  providerRetryPolicy(_provider) {
    return undefined
  }

  imageRequestPricing(_provider, _model) {
    return undefined
  }

  imageRequestTarget(_provider, _model, image) {
    return { width: image.width, height: image.height, maxBytes: image.bytes }
  }

  // Catalog entries need {provider,id,name} or llm's listModels throws
  // INVALID_CATALOG (packages/llm/llm/src/index.ts:718+).
  listModels(provider) {
    return Promise.resolve(
      (this.providers.find((p) => p.id === provider)?.models ?? []).map((m) => ({ provider, id: m.id, name: m.id })),
    )
  }

  resolveModel(provider, model) {
    const declared = this.providers.find((p) => p.id === provider)?.models?.find((m) => m.id === model)
    return Promise.resolve({ provider, id: model, name: model, contextWindow: declared?.contextWindow ?? 131072 })
  }

  async prepareCall(provider, model, signal) {
    return {
      model: await this.resolveModel(provider, model, signal),
      stream: (options) => this.stream(options),
    }
  }

  // --- scripted stream (MockAdapter minimal logic + gate-file barrier) ---

  async *stream(options) {
    const home = fakeHome()
    const key = options.sessionId === undefined ? 'anon' : String(options.sessionId)
    const callsPath = join(home, 'fake', 'scripts', `${key}.json`)
    // P5-05: delegated children (subagent/subagent_fork/workflow) get runtime-
    // assigned session ids the test cannot know upfront; a per-session script
    // miss falls back to scripts/default.json when it exists (sessions whose
    // ids ARE known always script themselves, so the fallback only ever serves
    // children). Without a default the original error is preserved.
    const readCalls = (p) => JSON.parse(readFileSync(p, 'utf8')).calls
    const cursor = this.cursors.get(key) ?? 0
    let calls
    try {
      calls = readCalls(callsPath)
    } catch (e) {
      if (e?.code !== 'ENOENT') throw e
      try {
        calls = readCalls(join(home, 'fake', 'scripts', 'default.json'))
      } catch (e2) {
        if (e2?.code !== 'ENOENT') throw e2
        throw new Error(`p2sdk-fake-llm: no scripted call #${cursor} for session ${key}`)
      }
    }
    this.cursors.set(key, cursor + 1)
    const call = calls[cursor]
    if (call === undefined) throw new Error(`p2sdk-fake-llm: no scripted call #${cursor} for session ${key}`)

    appendFileSync(
      join(home, 'fake', 'requests.jsonl'),
      `${JSON.stringify({
        ts: Date.now(),
        sessionId: options.sessionId === undefined ? null : String(options.sessionId),
        provider: options.provider,
        model: options.model,
        purpose: options.purpose ?? null,
        toolNames: (options.tools ?? []).map((t) => t.name).sort(),
        userTexts: options.messages
          .filter((m) => m.role === 'user')
          .map((m) => (m.content ?? []).filter((b) => b?.type === 'text').map((b) => b.text).join('')),
        // P5-06：子代理会话的 tool/result 网关不给直接 follow（P5-05 同款限制），
        // 上一轮工具结果随下一次模型调用回到这里 —— 记下来作为子会话格的观测通道。
        toolResults: options.messages
          .filter((m) => m.role === 'tool')
          .map((m) => ({
            toolCallId: m.toolCallId ?? null,
            isError: m.isError === true,
            text: (m.content ?? []).filter((b) => b?.type === 'text').map((b) => b.text).join(''),
          })),
      })}\n`,
    )

    let deltas = 0
    for (const chunk of call.chunks) {
      if (options.signal?.aborted) throw new Error('p2sdk-fake-llm: aborted')
      yield chunk
      if (chunk.type === 'text-delta' && call.gateAfterChunk === (deltas += 1)) {
        await waitForGate(join(home, 'gates', call.gateId), options.signal)
      }
      if (call.paceMs > 0) await sleep(call.paceMs)
    }
  }
}

export function apply(ctx, config = {}) {
  const providers = config.providers
  if (!Array.isArray(providers) || providers.length === 0) {
    throw new Error('p2sdk-fake-llm: config.providers must list the fake provider route')
  }
  for (const provider of providers) {
    if (typeof provider.id !== 'string' || provider.id.length === 0) {
      throw new Error('p2sdk-fake-llm: every provider needs a non-empty id')
    }
  }
  ctx.llm.registerAdapter(providers.map((p) => p.id), new FakeAdapter(providers))
}
